 "content": "from collections import Counter
from math import gcd


def _mode(values):
    return Counter(values).most_common(1)[0][0]


def _expand_lattice(coords):
    coords = sorted(set(coords))
    if len(coords) < 2:
        return coords
    pitch = 0
    for a, b in zip(coords, coords[1:]):
        pitch = gcd(pitch, b - a)
    if pitch < 1:
        return coords
    expanded = set(coords)
    for a, b in zip(coords, coords[1:]):
        expanded.update(range(a, b + 1, pitch))
    return sorted(expanded)


def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    # The two most frequent colors are the lattice and tile interior; rarer
    # colors are the symbols encoded by unanimous lattice-cell corners.
    common = {v for v, _ in freq.most_common(2)}
    symbols = set(freq) - common
    raw_rows = [r for r, row in enumerate(grid) if any(v in symbols for v in row)]
    raw_cols = [c for c in range(w) if any(grid[r][c] in symbols for r in range(h))]
    rows = _expand_lattice(raw_rows)
    cols = _expand_lattice(raw_cols)
    if len(rows) < 2 or len(cols) < 2:
        return [row[:] for row in grid]

    # Output blanks use the tile-interior color, not the separator color.
    inside = [grid[r][c] for r in range(h) for c in range(w)
              if r not in rows and c not in cols and grid[r][c] not in symbols]
    background = _mode(inside) if inside else _mode(
        v for row in grid for v in row if v not in symbols
    )

    out = []
    for r0, r1 in zip(rows, rows[1:]):
        line = []
        for c0, c1 in zip(cols, cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            value = corners[0]
            line.append(value if corners.count(value) == 4 and value in symbols else background)
        out.append(line)
    return out


def _check_received_demos():
    # Demo 1: 17x27 repeated tile scaffold with 0/2 junction symbols.
    d1 = []
    for r in range(17):
        if r == 1:
            row = [3] * 27
            row[14] = row[21] = 2
        elif r in (5, 9):
            row = [3] * 27
            row[0] = row[7] = 0
            row[14] = row[21] = 2
        elif r == 13:
            row = [3] * 27
        else:
            row = [3 if c in (0, 7, 14, 21) else 1 for c in range(27)]
        d1.append(row)
    assert transform(d1) == [[1, 1, 2], [0, 1, 2]]

    # Demo 2: 28x28, five by four tile cells. Rails carry 1/2/0 symbols.
    d2 = []
    for r in range(28):
        if r % 5 == 0:
            row = [5] * 28
            row[7] = row[13] = 1
            row[19] = row[25] = 2
            if r == 10:
                row[1] = 1
            if r in (20, 25):
                row[1] = row[7] = 0
                row[13] = row[19] = row[25] = 2
        else:
            row = [7 if c == 0 or c in range(2, 7) or c in range(8, 13)
                   or c in range(14, 19) or c in range(20, 25) or c >= 26
                   else 5 for c in range(28)]
        d2.append(row)
    assert transform(d2) == [
        [7, 1, 7, 2],
        [7, 1, 7, 2],
        [1, 1, 7, 2],
        [7, 7, 7, 7],
        [0, 7, 2, 7],
    ]

    # Demo 3: 25x29, one output row and four lattice-cell columns.
    d3 = []
    for r in range(25):
        if r in (1, 12):
            row = [0] * 29
            for c in (0, 7, 14):
                row[c] = 4
            row[21] = row[28] = 9
        elif r == 23:
            row = [0] * 29
        else:
            row = [0 if c in (0, 7, 14, 21, 28) else 2 for c in range(29)]
        d3.append(row)
    assert transform(d3) == [[4, 4, 2, 9]]


if __name__ == "__main__":
    _check_received_demos()
    print("all received demo checks passed")
    test = []
    for r in range(30):
        if r in (1, 14):
            row = [4] * 28
            row[0] = row[13] = row[26] = 7
        elif r == 27:
            row = [4] * 28
            row[0] = row[13] = 7
        else:
            row = [4 if c in (0, 13, 26) else 3 for c in range(28)]
        test.append(row)
    print(transform(test))


